import { styled, View } from '@tamagui/web';

import type { ItemMediaContract } from './Item.contract';
import { joinClasses } from './classes';
import type { ItemPartProps } from './types';
import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { pickWebInteractionHandlers } from '../../helpers/pickWebInteractionHandlers';
import { pickWebPressHandlers } from '../../helpers/pickWebPressHandlers';
import type { WebDivRef } from '../../types/WebElementAttributes';

export type ItemMediaProps = ItemPartProps<ItemMediaContract>;

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const itemMediaFrame = {
	display: 'flex',
	flexDirection: 'row',
	alignItems: 'center',
	flexShrink: 0,
	minWidth: 'auto',
	minHeight: 'auto',
	render: 'div',
	justifyContent: 'center',
	flexGrow: 0,
	flexBasis: 'auto',
} as const;

const itemMediaVariants = {
	default: {},
	icon: {
		width: '$size.x20',
		height: '$size.x20',
	},
	slot: {
		minWidth: '$size.x20',
		minHeight: '$size.x20',
	},
} as const;

// end of generated

const ItemMediaFrame = styled(View, {
	...itemMediaFrame,
	variants: { variant: itemMediaVariants },
});

/**
 * The leading avatar, icon or thumbnail of an `Item`. Its box fits its child, so the child's size sets the row height.
 */
const ItemMedia = (props: ItemMediaProps) => {
	const { variant = 'default', children } = props;
	const classes = joinClasses(variant === 'icon' ? 'rcx-item__media rcx-item__media--icon' : 'rcx-item__media', props.className);

	return (
		<ItemMediaFrame
			variant={variant}
			className={classes}
			render={
				<div
					{...ariaAndDataAttributes(props)}
					{...pickWebInteractionHandlers(props)}
					{...pickWebPressHandlers(props)}
					ref={props.ref as WebDivRef}
					id={props.id}
					title={props.title}
					role={props.role}
					tabIndex={props.tabIndex}
				/>
			}
		>
			{children}
		</ItemMediaFrame>
	);
};

export default ItemMedia;
